INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','medium','mcq','A 7-year-old boy presents with haematuria, periorbital oedema, and oliguria 2 weeks after a sore throat. Serum C3 is low and antistreptolysin O (ASO) titres are elevated. What is the characteristic renal biopsy finding on immunofluorescence?','["A. Granular (''starry sky'') IgG and C3 deposits along the glomerular capillary walls and mesangium","B. Linear IgG deposits along the glomerular basement membrane","C. Mesangial IgA deposits","D. Negative immunofluorescence with foot process effacement on electron microscopy"]','A','Post-streptococcal GN shows granular ''starry sky'' or ''lumpy-bumpy'' IgG and C3 deposits due to immune complex deposition. Linear IgG is seen in Goodpasture syndrome; mesangial IgA in IgA nephropathy; negative IF with foot process effacement in minimal change disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','easy','mcq','IgA nephropathy (Berger disease) most characteristically presents with which of the following?','["A. Nephrotic syndrome with heavy proteinuria in adults","B. Recurrent episodes of macroscopic haematuria coinciding with upper respiratory tract infections","C. Haematuria appearing 2-3 weeks after pharyngitis","D. Rapidly progressive renal failure with linear IgG deposits"]','B','IgA nephropathy classically presents with recurrent macroscopic haematuria that coincides with (or shortly after) upper respiratory infections — ''synpharyngitic haematuria''. The haematuria in post-streptococcal GN typically occurs 1-3 weeks after the infection, unlike IgA nephropathy where it is simultaneous.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','hard','mcq','Rapidly progressive (crescentic) glomerulonephritis (RPGN) Type I (anti-GBM disease / Goodpasture syndrome) is distinguished from Type III (pauci-immune) RPGN by which finding?','["A. Presence of crescents on light microscopy","B. Linear IgG deposits along the glomerular basement membrane on immunofluorescence","C. Negative ANCA serology","D. Rapidly deteriorating renal function over weeks"]','C','Type I RPGN (Goodpasture) shows linear IgG and C3 along the GBM on immunofluorescence — caused by anti-GBM antibodies. Type III (pauci-immune RPGN) is ANCA-positive (p-ANCA or c-ANCA) but shows minimal or no immunoglobulin deposits on IF. Both types show crescents and rapid deterioration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','medium','mcq','Crescents seen in rapidly progressive glomerulonephritis are formed by proliferation of which cell types?','["A. Mesangial cells and endothelial cells","B. Podocytes (visceral epithelial cells) and smooth muscle cells","C. Parietal epithelial cells of Bowman capsule and infiltrating monocytes/macrophages","D. Tubular epithelial cells and fibroblasts"]','D','Crescents in RPGN are formed by proliferation of parietal epithelial cells lining Bowman capsule along with infiltrating monocytes and macrophages. They compress the glomerular tuft and cause rapid loss of GFR. This is the histologic hallmark of all three types of RPGN.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','easy','mcq','Post-streptococcal glomerulonephritis is caused by which of the following?','["A. Direct invasion of glomeruli by Group A beta-haemolytic Streptococcus","B. Deposition of circulating immune complexes containing streptococcal antigens in the glomerulus","C. Molecular mimicry between streptococcal antigens and GBM collagen","D. Activation of alternative complement pathway by streptococcal lipopolysaccharide"]','A','Post-streptococcal GN is caused by deposition of circulating immune complexes (containing streptococcal antigens such as nephritis-associated plasmin receptor — NAPIr — and streptococcal pyrogenic exotoxin B — SPEB) in the glomerulus. The bacteria do not directly invade the kidney.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','medium','mcq','A patient with haemoptysis and rapidly progressive renal failure is found to have linear IgG deposits on kidney biopsy. Anti-GBM antibodies are detected in the serum. Which antigen is the primary target in this condition?','["A. Alpha-3 chain of type IV collagen","B. Alpha-1 chain of type I collagen","C. Phospholipase A2 receptor (PLA2R)","D. Nephrin (slit-diaphragm protein)"]','B','Goodpasture syndrome (Type I RPGN) is caused by antibodies against the alpha-3 chain of type IV collagen, which is a major component of both the glomerular basement membrane and the alveolar basement membrane. This explains the dual lung and kidney involvement (pulmonary haemorrhage + RPGN).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','hard','mcq','On electron microscopy of a patient with post-streptococcal GN, which ultrastructural finding is pathognomonic?','["A. Subepithelial ''spike and dome'' deposits","B. Mesangial electron-dense deposits","C. Subepithelial ''hump-shaped'' electron-dense deposits","D. Effacement of podocyte foot processes without immune deposits"]','C','Post-streptococcal GN classically shows subepithelial ''hump-shaped'' electron-dense immune complex deposits on electron microscopy. These correspond to the subepithelial deposits that give the ''starry sky'' pattern on immunofluorescence. Subepithelial spikes are seen in membranous nephropathy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','medium','mcq','IgA nephropathy on immunofluorescence characteristically shows deposits in which location?','["A. Linear deposits along the GBM","B. Granular subepithelial deposits","C. Mesangial IgA deposits (with or without IgG and C3)","D. Subendothelial IgM deposits"]','D','IgA nephropathy (Berger disease) is characterised by mesangial deposits of IgA, often with IgG and C3, on immunofluorescence. This reflects the pathogenesis: circulating IgA immune complexes (often containing galactose-deficient IgA1) deposit in the mesangium and trigger complement activation and mesangial proliferation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','easy','mcq','Which serological markers would be most useful to order for a child with post-streptococcal glomerulonephritis to confirm prior streptococcal infection?','["A. Anti-nuclear antibody (ANA) and anti-dsDNA","B. ANCA (p-ANCA and c-ANCA)","C. Anti-streptolysin O (ASO) titre and anti-DNase B","D. Anti-GBM antibodies"]','A','ASO titre and anti-DNase B are streptococcal antibodies that confirm prior Group A beta-haemolytic streptococcal infection. ASO is elevated after pharyngeal infections; anti-DNase B is more sensitive for skin infections (impetigo). ANCA is used for pauci-immune RPGN; anti-GBM for Goodpasture; ANA/anti-dsDNA for lupus nephritis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephritic','hard','mcq','A 35-year-old man presents with haematuria, proteinuria, and sensorineural hearing loss. His mother had the same condition and required dialysis at age 40. Renal biopsy electron microscopy shows irregular thinning and splitting of the GBM with a ''basket-weave'' appearance. What is the most likely diagnosis?','["A. IgA nephropathy","B. Alport syndrome (hereditary nephritis)","C. Thin basement membrane disease","D. Focal segmental glomerulosclerosis"]','B','Alport syndrome (hereditary nephritis) is an X-linked (most commonly) disorder caused by mutations in COL4A5 (type IV collagen alpha-5 chain). It presents with haematuria, progressive renal failure, sensorineural hearing loss, and ocular abnormalities. EM shows irregular thinning, thickening, and splitting (''lamellation'' or ''basket-weave'' pattern) of the GBM.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','easy','mcq','A 4-year-old child presents with periorbital oedema and heavy proteinuria (>40 mg/m2/hr). Serum albumin is 1.8 g/dL. Renal biopsy shows normal glomeruli on light microscopy with diffuse foot process effacement on electron microscopy. What is the most likely diagnosis?','["A. Minimal change disease (lipoid nephrosis)","B. Focal segmental glomerulosclerosis","C. Membranous nephropathy","D. Diabetic nephropathy"]','A','Minimal change disease (MCD) is the most common cause of nephrotic syndrome in children. Light microscopy is normal, but electron microscopy shows diffuse effacement of podocyte foot processes. It is highly responsive to steroids. It is associated with Hodgkin lymphoma in adults and atopic conditions in children.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','medium','mcq','Membranous nephropathy on electron microscopy shows which characteristic finding?','["A. Mesangial electron-dense deposits and mesangial hypercellularity","B. Subepithelial electron-dense deposits with intervening basement membrane ''spikes''","C. Subendothelial and mesangial deposits with double-contoured GBM","D. Diffuse effacement of foot processes without immune complex deposits"]','B','Membranous nephropathy shows subepithelial immune complex deposits (IgG and C3) on IF and EM. As the GBM attempts to surround these deposits, basement membrane material is laid down between them, creating the characteristic ''spike and dome'' pattern on silver stain and EM. PLA2R antibodies are positive in ~70% of idiopathic cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','medium','mcq','Focal segmental glomerulosclerosis (FSGS) is characterised by which pathological feature?','["A. Sclerosis affecting some (focal) glomeruli and only part (segmental) of those glomeruli","B. Uniform diffuse sclerosis of all glomeruli","C. Mesangial hypercellularity with IgA deposits","D. Membranous pattern with subepithelial spike deposits"]','C','FSGS is defined by focal (affecting some but not all glomeruli) and segmental (involving only a portion of each affected glomerulus) sclerosis and hyalinosis. It is the most common cause of nephrotic syndrome in adults in some populations, particularly Black adults, and is associated with HIV infection, heroin use, and reduced renal mass.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','hard','mcq','Which of the following is the most important pathogenetic mechanism in minimal change disease?','["A. Anti-GBM antibody deposition","B. Circulating immune complex deposition in subepithelial space","C. T-cell dysfunction resulting in production of a circulating permeability factor that injures podocytes","D. Alternative complement pathway activation with C3 nephritic factor"]','D','Minimal change disease is thought to be caused by T-lymphocyte dysfunction, resulting in production of a circulating ''permeability factor'' (possibly vascular endothelial growth factor or interleukin-13) that injures podocytes and causes foot process effacement. There are no immune complex deposits, which distinguishes it from membranous nephropathy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','easy','mcq','What is the classic tetrad of features in nephrotic syndrome?','["A. Haematuria, hypertension, proteinuria, oliguria","B. Haematuria, azotaemia, hypertension, oedema","C. Proteinuria (>3.5 g/day), hypoalbuminaemia, generalised oedema, hyperlipidaemia and lipiduria","D. Proteinuria, haematuria, red cell casts, hypertension"]','A','Nephrotic syndrome is defined by: (1) massive proteinuria >3.5 g/day (or >40 mg/m2/hr in children), (2) hypoalbuminaemia <3 g/dL, (3) generalised oedema (anasarca), and (4) hyperlipidaemia with lipiduria (oval fat bodies, fatty casts). Haematuria and hypertension are features of nephritic syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','medium','mcq','A 60-year-old man with a 3-year history of type 2 diabetes presents with nephrotic-range proteinuria. Renal biopsy shows diffuse glomerular basement membrane thickening and mesangial expansion. Nodular deposits are present in the peripheral mesangium. What are these nodular deposits called?','["A. Wire-loop lesions","B. Kimmelstiel-Wilson nodules","C. Sclerotic segments","D. Foam cell accumulations"]','B','Kimmelstiel-Wilson nodules (nodular glomerulosclerosis) are the pathognomonic lesion of diabetic nephropathy. They represent nodular deposits of laminated matrix material in the peripheral mesangium. They are seen in both type 1 and type 2 diabetes and represent advanced diabetic glomerular disease. Wire-loop lesions are seen in lupus nephritis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','hard','mcq','In membranous nephropathy, what is the target antigen in the majority of idiopathic cases?','["A. Alpha-3 chain of type IV collagen","B. Neutral endopeptidase (NEP)","C. Phospholipase A2 receptor (PLA2R) on podocytes","D. Vascular endothelial growth factor receptor"]','C','Anti-phospholipase A2 receptor (PLA2R) antibodies are found in approximately 70% of idiopathic (primary) membranous nephropathy cases. PLA2R is expressed on podocyte foot processes. In situ immune complex formation occurs when circulating anti-PLA2R IgG4 antibodies bind to podocyte PLA2R, triggering complement activation and GBM spike formation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','medium','mcq','Which of the following is the most common cause of nephrotic syndrome in adults in Western countries?','["A. Minimal change disease","B. IgA nephropathy","C. Focal segmental glomerulosclerosis","D. Membranous nephropathy"]','D','Focal segmental glomerulosclerosis (FSGS) has emerged as the most common cause of nephrotic syndrome in adults in the United States, particularly in Black patients. Membranous nephropathy is the most common cause in white adults over 40. Minimal change disease is the most common in children.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','easy','mcq','Lipid nephrosis (minimal change disease) is associated with which of the following conditions in adults?','["A. Hodgkin lymphoma","B. Multiple myeloma","C. Hepatitis B infection","D. Colon carcinoma"]','A','Minimal change disease in adults has a well-known association with Hodgkin lymphoma. The nephrotic syndrome may precede, accompany, or follow the diagnosis of lymphoma. It is thought that lymphoma-derived cytokines (particularly T-cell cytokines) cause podocyte injury and foot process effacement. Treatment of the lymphoma often leads to resolution of the nephrotic syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Glomerulonephritis - Nephrotic','hard','mcq','Which of the following mutations is associated with a hereditary form of focal segmental glomerulosclerosis resistant to steroids?','["A. COL4A5 mutation","B. NPHS2 (podocin) or NPHS1 (nephrin) mutation","C. PKD1 mutation","D. WT1 mutation"]','B','Hereditary FSGS is most commonly caused by mutations in NPHS2 (encoding podocin) or NPHS1 (encoding nephrin), which are components of the slit diaphragm complex. These forms are typically steroid-resistant and may progress to ESRD. Nephrin and podocin maintain the filtration barrier. COL4A5 mutations cause Alport syndrome; PKD1 causes ADPKD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','easy','mcq','A 70-year-old man develops oliguria and rising creatinine 2 days after cardiac surgery associated with significant intraoperative hypotension. Urine microscopy shows muddy brown granular casts. What is the most likely diagnosis?','["A. Ischaemic acute tubular necrosis (ATN)","B. Acute interstitial nephritis","C. Pre-renal acute kidney injury","D. Obstructive uropathy"]','A','Ischaemic ATN occurs when prolonged hypotension (as in surgery, shock, or sepsis) causes ischaemia of the renal tubular epithelium. The classic urine finding is muddy brown granular casts — representing sloughed tubular epithelial cells. Pre-renal AKI would show bland urine with concentrated urine (high osmolarity), not muddy brown casts.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','medium','mcq','Which urinary finding best helps distinguish pre-renal acute kidney injury from established intrinsic (ischaemic) ATN?','["A. Urine osmolality >500 mOsm/kg and fractional excretion of sodium (FENa) <1% in pre-renal AKI","B. Muddy brown casts and FENa >2% in pre-renal AKI","C. Red cell casts and proteinuria in ATN","D. White cell casts in ATN"]','B','In pre-renal AKI, the tubules are intact so they maximally reabsorb sodium and water: urine is concentrated (osmolality >500 mOsm/kg), urine sodium is low (<20 mEq/L), and FENa is <1%. In established ATN, tubular damage impairs reabsorption: urine is dilute, urine sodium is high (>40 mEq/L), FENa is >2%, and muddy brown granular casts are present.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','medium','mcq','Which segment of the renal tubule is most vulnerable to ischaemic injury?','["A. Proximal convoluted tubule and the thick ascending limb of Henle","B. Distal convoluted tubule","C. Collecting duct","D. Thin descending limb of Henle"]','C','The proximal convoluted tubule and the thick ascending limb of the loop of Henle are the most metabolically active segments and have the highest oxygen demand. They are most vulnerable to ischaemia. These segments also concentrate toxins, making them susceptible to toxic ATN. The medullary thick ascending limb is particularly vulnerable due to the relatively hypoxic medullary environment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','hard','mcq','Aminoglycoside-induced ATN most characteristically affects which nephron segment, and what is the key mechanism?','["A. Glomerulus — direct binding to podocytes causing foot process effacement","B. Collecting duct — antidiuretic hormone antagonism","C. Proximal tubular cells — direct toxic injury following drug accumulation in tubular epithelial cells","D. Thick ascending limb — sodium-potassium-chloride cotransporter (NKCC2) inhibition"]','D','Aminoglycosides accumulate in proximal tubular epithelial cells via endocytosis after filtration. They directly damage mitochondria, generate reactive oxygen species, and activate apoptotic pathways in proximal tubular cells. This leads to patchy tubular necrosis with loss of brush border, cell detachment, and intraluminal cast formation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','easy','mcq','Which of the following is an example of post-renal acute kidney injury?','["A. Severe haemorrhagic shock","B. Bilateral ureteric obstruction by pelvic malignancy","C. Contrast nephropathy after CT scan","D. Glomerulonephritis from systemic lupus erythematosus"]','A','Post-renal AKI is caused by obstruction to urine flow distal to the renal parenchyma. Bilateral ureteric obstruction (e.g., by pelvic tumour, retroperitoneal fibrosis, or bilateral renal calculi) is a classic cause. It is important to recognise because relieving the obstruction can restore renal function. Contrast nephropathy and glomerulonephritis are intrinsic (intra-renal) causes.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','medium','mcq','In the maintenance phase of ATN, what is the typical urine output range?','["A. Normal (>0.5 mL/kg/hr)","B. Between 40 and 400 mL/day (oliguria)","C. Complete anuria (<10 mL/day)","D. Polyuria (>3 L/day)"]','B','The maintenance phase of ATN is characterised by sustained oliguria (urine output 40-400 mL/day), rising BUN and creatinine, electrolyte abnormalities (hyperkalaemia, hyperphosphataemia, metabolic acidosis), and fluid overload. This phase typically lasts 10-14 days but can be longer. The recovery phase is marked by diuresis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','hard','mcq','Haemoglobin and myoglobin can cause toxic ATN. Which mechanism explains myoglobin-induced tubular injury?','["A. Direct complement activation on tubular cells","B. Tubular obstruction by myoglobin casts, direct haem protein toxicity, and free radical-mediated oxidative damage","C. Myoglobin antibody immune complex deposition","D. Myoglobin-induced renal vasoconstriction via endothelin release only"]','C','Myoglobin (from rhabdomyolysis) causes ATN through three mechanisms: (1) tubular obstruction by myoglobin casts, (2) direct haem protein toxicity to tubular epithelial cells, and (3) free radical-mediated oxidative injury (Fenton reaction). Volume depletion and aciduria potentiate myoglobin precipitation in tubules. Treatment includes aggressive fluid resuscitation and urinary alkalinisation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','medium','mcq','In ATN, what is the hallmark finding on light microscopy of the kidney?','["A. Glomerular crescent formation","B. Interstitial eosinophilic infiltrate","C. Tubular epithelial cell necrosis with loss of brush border, loss of nuclei, and cast formation; with relative preservation of tubular basement membrane","D. Nodular mesangial matrix expansion"]','D','The classic light microscopy finding in ATN shows necrosis of tubular epithelial cells (most pronounced in the S3 segment of the proximal tubule and thick ascending limb). Findings include loss of brush border, nuclear pyknosis/karyolysis, sloughing of cells into the lumen (forming granular/muddy-brown casts). The tubular basement membrane is often intact, allowing regeneration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','easy','mcq','Which of the following conditions most commonly causes pre-renal acute kidney injury?','["A. Severe dehydration, haemorrhage, or cardiac failure leading to reduced renal perfusion","B. NSAIDs causing direct tubular toxicity","C. Bilateral renal artery stenosis","D. Acute glomerulonephritis"]','A','Pre-renal AKI is caused by reduced renal perfusion without intrinsic renal damage. Common causes include volume depletion (bleeding, diarrhoea, burns, vomiting), reduced cardiac output (heart failure, cardiogenic shock), and distributive shock (sepsis). The renal parenchyma is initially intact and function recovers with restoration of perfusion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Acute Kidney Injury','hard','mcq','Contrast-induced nephropathy typically affects which nephron segment and through what mechanism?','["A. Glomerulus via complement-mediated injury","B. Outer medullary proximal tubule and thick ascending limb via direct cytotoxicity and medullary ischaemia from vasoconstriction","C. Collecting duct via aquaporin-2 downregulation","D. Distal tubule via calcium crystal deposition"]','B','Contrast-induced nephropathy damages the outer medullary proximal tubule S3 segment and thick ascending limb through two mechanisms: (1) direct cytotoxic effects of iodinated contrast on tubular epithelium (reactive oxygen species generation), and (2) contrast causes renal medullary vasoconstriction (via adenosine and endothelin) in an already hypoxic region. Risk factors include CKD, diabetes, volume depletion, and high contrast doses.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','easy','mcq','According to KDIGO guidelines, which GFR (mL/min/1.73m2) defines stage 3a chronic kidney disease?','["A. GFR 45-59 mL/min/1.73m2","B. GFR 60-89 mL/min/1.73m2","C. GFR 30-44 mL/min/1.73m2","D. GFR 15-29 mL/min/1.73m2"]','A','KDIGO CKD stages: G1 (GFR ≥90), G2 (60-89), G3a (45-59), G3b (30-44), G4 (15-29), G5 (<15 or on dialysis). Stage 3 represents moderate decrease in GFR with significant risk of complications. CKD is defined as structural or functional abnormalities for >3 months with health implications.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','medium','mcq','The most common causes of end-stage renal disease (ESRD) requiring dialysis in Western countries are:','["A. IgA nephropathy and lupus nephritis","B. Diabetic nephropathy and hypertensive nephrosclerosis","C. Polycystic kidney disease and chronic pyelonephritis","D. Membranous nephropathy and FSGS"]','B','Diabetic nephropathy (approximately 40-44%) and hypertensive nephrosclerosis (approximately 25-30%) are the two most common causes of ESRD requiring dialysis in Western countries. Diabetic nephropathy is the leading cause overall. The rising prevalence of type 2 diabetes has made this an increasingly important public health issue.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','medium','mcq','The key histological finding that characterises the irreversible progression of chronic kidney disease, regardless of the initial aetiology, is:','["A. Glomerular crescent formation","B. Tubular vacuolisation","C. Interstitial fibrosis and tubular atrophy (IFTA)","D. Mesangial IgA deposits"]','C','Interstitial fibrosis and tubular atrophy (IFTA) is the final common pathway of chronic renal injury regardless of the initial cause (glomerular, vascular, or tubular). Histologically it manifests as fibrosis of the interstitium and atrophy/loss of tubules. The degree of IFTA on biopsy is the best histological predictor of long-term renal prognosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','hard','mcq','Renal osteodystrophy in CKD occurs primarily due to which sequence of events?','["A. Decreased erythropoietin leading to anaemia → reduced bone marrow activity → osteoclast activation","B. Reduced renal 1-alpha-hydroxylase activity → decreased calcitriol → hypocalcaemia → secondary hyperparathyroidism → bone resorption","C. Accumulation of urea → direct suppression of osteoblasts","D. Metabolic alkalosis → calcium precipitation in bone"]','D','CKD causes reduced activity of renal 1-alpha-hydroxylase, the enzyme that converts 25-hydroxyvitamin D to active calcitriol (1,25-dihydroxyvitamin D3). Reduced calcitriol leads to decreased intestinal calcium absorption and hypocalcaemia. This stimulates parathyroid glands (secondary hyperparathyroidism) → PTH-mediated osteoclast activation → bone resorption → renal osteodystrophy (osteitis fibrosa cystica).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','easy','mcq','Which of the following is an expected haematological complication of advanced CKD?','["A. Polycythaemia due to increased erythropoietin","B. Normochromic normocytic anaemia due to decreased erythropoietin production","C. Iron deficiency anaemia from increased GI blood loss","D. Haemolytic anaemia from complement activation"]','A','CKD causes normochromic normocytic anaemia primarily because the damaged kidneys cannot produce sufficient erythropoietin (EPO), which is normally produced by peritubular fibroblasts/interstitial cells. Additional contributing factors include iron deficiency, chronic inflammation, shortened red cell survival, and uraemic inhibition of erythropoiesis. Treatment includes recombinant EPO and iron supplementation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','medium','mcq','Which cardiovascular complication is the leading cause of death in patients with CKD?','["A. Stroke","B. Cardiovascular disease (ischaemic heart disease, heart failure, sudden cardiac death)","C. Pulmonary embolism","D. Infective endocarditis"]','B','Cardiovascular disease (CVD) — including ischaemic heart disease, heart failure, and sudden cardiac death — is the leading cause of death in CKD patients, accounting for >50% of deaths. CKD is an independent risk factor for CVD. Contributing factors include hypertension, dyslipidaemia, anaemia, fluid overload, uraemic toxins causing endothelial dysfunction, and accelerated vascular calcification.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','hard','mcq','In CKD, the kidney develops a characteristic ''end-stage'' appearance. Which gross pathological feature best describes end-stage kidneys?','["A. Enlarged, smooth, pale kidneys with cortical cysts","B. Bilaterally shrunken, granular, fibrotic kidneys with thinned cortex","C. Normal-sized kidneys with haemorrhagic infarcts","D. Enlarged kidneys with multiple bilateral cysts"]','C','End-stage kidneys from any cause typically appear bilaterally small and shrunken, with a granular cortical surface, thinned cortex (due to nephron loss and IFTA), and widened pelves (due to compensatory dilatation). Microscopically, there is widespread IFTA, glomerulosclerosis, vascular sclerosis, and marked reduction in functioning nephrons.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','medium','mcq','Hyperkalaemia in CKD becomes life-threatening primarily because of which effect?','["A. Cardiac arrhythmias — peaked T waves, widened QRS, ventricular fibrillation","B. Respiratory muscle paralysis","C. Cerebral oedema and seizures","D. Metabolic alkalosis exacerbation"]','D','Hyperkalaemia in CKD is dangerous primarily due to cardiac toxicity: it reduces the resting membrane potential, leading to ECG changes (peaked T waves → prolonged PR → widened QRS → sine wave pattern → ventricular fibrillation/asystole). Treatment includes IV calcium gluconate (membrane stabilisation), insulin+dextrose (shift K into cells), and dialysis for severe or refractory hyperkalaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','easy','mcq','Which acid-base disturbance is characteristic of advanced CKD?','["A. Metabolic alkalosis with hypokalaemia","B. Respiratory acidosis with CO2 retention","C. High anion gap metabolic acidosis due to retention of sulphate, phosphate, and organic acids","D. Respiratory alkalosis from hyperventilation"]','A','CKD causes high anion gap metabolic acidosis (HAGMA) because the failing kidneys cannot excrete the daily acid load (sulphate, phosphate, hippurate, urate, other organic anions). As GFR falls, these anions accumulate and expand the anion gap. This acidosis contributes to bone dissolution, protein catabolism, and accelerated muscle wasting in CKD patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Chronic Kidney Disease','hard','mcq','The ''intact nephron hypothesis'' best explains which clinical observation in CKD?','["A. Kidneys shrink in size before GFR falls below normal","B. Proteinuria appears only after 75% nephron loss","C. Despite loss of nephrons, remaining nephrons undergo compensatory hypertrophy and hyperfiltration, maintaining overall GFR until >75% nephrons are destroyed — but this compensatory hyperfiltration ultimately accelerates progression","D. Anaemia appears in early CKD before metabolic acidosis"]','B','The intact nephron hypothesis (Brenner) states that when nephrons are lost, remaining nephrons compensate by hypertrophy and increase their individual GFR (hyperfiltration). This maintains overall GFR until >75% nephrons are destroyed, explaining why patients can remain asymptomatic with significant nephron loss. However, chronic glomerular hypertension from hyperfiltration induces focal segmental sclerosis in remaining nephrons, accelerating progression to ESRD — this is the rationale for using ACE inhibitors/ARBs in CKD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','medium','mcq','A patient on methicillin (or NSAIDs) develops fever, rash, eosinophilia, and acute renal failure. Urine microscopy shows white cell casts and eosinophiluria. What is the most likely diagnosis?','["A. Acute pyelonephritis","B. Acute drug-induced (hypersensitivity) interstitial nephritis","C. Acute tubular necrosis","D. IgA nephropathy"]','A','Acute drug-induced interstitial nephritis (AIN) is a hypersensitivity reaction characterised by the triad of fever, rash, and eosinophilia appearing 2-40 weeks after starting a culprit drug (classically penicillins/methicillin, NSAIDs, PPIs, sulphonamides, rifampicin). Renal biopsy shows interstitial oedema and an infiltrate of lymphocytes, plasma cells, and eosinophils. Eosinophiluria (Hansel stain) is a useful but insensitive diagnostic finding.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','medium','mcq','Fanconi syndrome is characterised by generalised proximal tubular dysfunction. Which combination of urinary losses is characteristic?','["A. Aminoaciduria, glycosuria, phosphaturia, uricosuria, and renal tubular acidosis (type 2)","B. Hyperchloraemic acidosis, hyperkalaemia, and hypomagnesaemia","C. Haematuria, proteinuria, and red cell casts","D. Hypernatraemia, polyuria, and nephrogenic diabetes insipidus"]','B','Fanconi syndrome results from generalised proximal tubular dysfunction causing urinary wasting of all solutes normally reabsorbed in the proximal tubule: glucose (despite normal blood glucose), amino acids, phosphate, urate, bicarbonate (causing type 2 RTA), potassium, and sodium. Causes include Wilson disease, galactosaemia, multiple myeloma (light chains), tenofovir (antiretroviral), and lead poisoning.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','medium','mcq','Reflux nephropathy (chronic pyelonephritis due to vesicoureteral reflux) most characteristically produces which gross pathological appearance?','["A. Bilateral symmetric cortical scarring","B. Coarse, irregular, asymmetric cortical scars overlying dilated blunted calyces (especially at poles)","C. Smooth cortical surface with uniform cortical thinning","D. Multiple cortical cysts bilaterally"]','C','Reflux nephropathy (chronic atrophic pyelonephritis) produces coarse, irregular, asymmetric cortical scars that overlie dilated and blunted calyces — most prominent at the upper and lower poles where compound papillae allow intrarenal reflux. This pattern is distinct from other forms of CKD which produce diffuse, smooth cortical atrophy. Voiding cystourethrogram (VCUG) confirms vesicoureteral reflux.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','hard','mcq','Light chain cast nephropathy (''myeloma kidney'') occurs due to which mechanism?','["A. Monoclonal light chains precipitate in tubular lumens, activate tubular cells, and cause interstitial inflammation and fibrosis","B. Light chains deposit as amyloid in glomeruli causing nephrotic syndrome","C. Myeloma cells directly infiltrate the renal interstitium","D. Hypercalcaemia from myeloma causes nephrocalcinosis and ATN"]','D','Light chain (Bence Jones) cast nephropathy occurs when filtered monoclonal light chains bind to Tamm-Horsfall protein in the distal tubule, forming obstructive intratubular casts. The tubular cells surrounding these casts undergo necrosis and the casts elicit a multinucleated giant cell reaction. This causes tubular atrophy, interstitial fibrosis, and progressive renal failure. It is the most common renal complication of multiple myeloma.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','easy','mcq','Chronic interstitial nephritis caused by long-term NSAID use (analgesic nephropathy) most characteristically affects which part of the kidney?','["A. Glomeruli — causing membranous nephropathy","B. Renal papillae — causing papillary necrosis","C. Proximal tubules — causing Fanconi syndrome","D. Collecting ducts — causing nephrogenic DI"]','A','Analgesic nephropathy (chronic NSAID/phenacetin use) classically causes renal papillary necrosis. The renal papillae have a relatively poor blood supply and are susceptible to ischaemia and direct toxicity from analgesic metabolites concentrated in the medulla. Necrotic papillae may slough off and cause renal colic, obstruction, or haematuria. CT shows a ring shadow around the calcified papilla.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','medium','mcq','In acute pyelonephritis, what is the pathognomonic urinary cast type?','["A. Red cell casts","B. White cell (leucocyte) casts","C. Muddy brown granular casts","D. Fatty casts"]','B','White cell (leucocyte) casts are pathognomonic of pyelonephritis (and can also be seen in severe interstitial nephritis). They form when neutrophils aggregate in tubular lumens and become incorporated into Tamm-Horsfall protein matrices. Their presence confirms the infection is in the kidney (upper UTI), rather than a lower UTI where WBCs in urine would not form casts.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','hard','mcq','Vesicoureteral reflux (VUR) predisposes to intrarenal reflux and ascending infection primarily through which mechanism?','["A. VUR causes bladder outlet obstruction increasing urinary stasis","B. High-pressure VUR with reflux into compound papillae (especially at poles) allows bacteria-laden urine to enter collecting ducts","C. VUR damages the ureterovesical junction causing hydronephrosis and urinary stasis","D. VUR causes haematogenous seeding of the renal parenchyma"]','C','Intrarenal reflux occurs when infected urine in the renal pelvis refluxes into collecting ducts through papillary orifices. This is more likely with ''compound'' papillae (found at the poles) whose orifices are slit-shaped and more easily patent with increased pressure. ''Simple'' papillae (at the mid-poles) have concave openings that close under pressure, resisting intrarenal reflux.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','medium','mcq','A patient develops acute renal failure with haematuria after starting allopurinol. Renal biopsy shows interstitial infiltrate with eosinophils and lymphocytes. Serum creatinine normalises after stopping the drug. What is the mechanism of this drug-induced renal injury?','["A. Direct tubular toxicity from uric acid reduction","B. Immune-mediated type IV hypersensitivity reaction targeting tubulo-interstitial cells","C. Complement-mediated glomerular injury","D. Crystalline nephropathy from xanthine accumulation"]','D','Drug-induced acute interstitial nephritis (AIN) is a type IV (delayed-type, T-cell mediated) hypersensitivity reaction. The drug (or its metabolite) acts as a hapten, triggering T-cell sensitisation against tubulo-interstitial antigens. Subsequent exposure leads to CD4+ T-cell-mediated recruitment of eosinophils, lymphocytes, and plasma cells into the interstitium. Removal of the offending drug leads to recovery in most cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','easy','mcq','Urate nephropathy can present in which two forms?','["A. Acute uric acid nephropathy (tubular obstruction from urate crystals) and chronic tophaceous nephropathy","B. Acute glomerulonephritis and chronic nephrotic syndrome","C. Acute papillary necrosis and chronic medullary sponge kidney","D. Acute ATN and chronic reflux nephropathy"]','A','Urate nephropathy occurs in two forms: (1) Acute uric acid nephropathy — massive uricosuria (e.g., tumour lysis syndrome) causes urate crystal precipitation in collecting ducts causing acute AKI; (2) Chronic urate nephropathy (gouty nephropathy) — long-term hyperuricaemia causes interstitial deposition of monosodium urate crystals (''tophi'') with a foreign body giant cell reaction, leading to chronic interstitial nephritis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Tubular and Interstitial Disease','hard','mcq','Hypercalcaemia causes renal damage through which primary mechanism in nephrocalcinosis?','["A. Calcium binds to the GBM causing membranous nephropathy","B. Elevated calcium activates NLRP3 inflammasome in podocytes","C. Calcium deposits in tubular epithelium and interstitium cause direct tubular toxicity, tubular obstruction, and interstitial inflammation leading to nephrocalcinosis","D. Hypercalcaemia-induced renal vasoconstriction causes ischaemic ATN"]','B','Hypercalcaemia (from hyperparathyroidism, vitamin D toxicity, sarcoidosis, malignancy, etc.) causes nephrocalcinosis: calcium phosphate and calcium oxalate crystals deposit in tubular epithelium and the interstitium. This causes direct tubular cell toxicity, tubular obstruction, and interstitial calcification/inflammation. Grossly, the cortex and medulla may show chalky-white deposits (''calcium dust'').','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','easy','mcq','Autosomal dominant polycystic kidney disease (ADPKD) is most commonly caused by mutations in which gene?','["A. PKD1 (encoding polycystin-1) on chromosome 16","B. PKD2 (encoding polycystin-2) on chromosome 4","C. PKHD1 (encoding fibrocystin) on chromosome 6","D. TSC1 (encoding hamartin) on chromosome 9"]','A','ADPKD is caused by mutations in PKD1 (chromosome 16, encoding polycystin-1 — approximately 85% of cases) or PKD2 (chromosome 4, encoding polycystin-2 — approximately 15% of cases). PKD1 mutations cause a more severe phenotype with earlier onset of ESRD (mean ~54 years) compared to PKD2 (~74 years). Polycystins are localised to primary cilia and regulate calcium signalling.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','medium','mcq','Which extra-renal manifestation is most commonly associated with ADPKD?','["A. Hepatic cysts (in up to 83% of patients)","B. Pancreatic cysts causing diabetes","C. Ovarian cysts","D. Cardiac rhabdomyomas"]','B','Hepatic cysts are the most common extra-renal manifestation of ADPKD, present in up to 83% of patients (though liver failure is rare). Other extra-renal manifestations include intracranial (Berry) aneurysms (~10-40% — risk of subarachnoid haemorrhage), mitral valve prolapse, colonic diverticula, and seminal vesicle cysts. Cardiac rhabdomyomas are associated with tuberous sclerosis (TSC1/TSC2 mutations).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','medium','mcq','Autosomal recessive polycystic kidney disease (ARPKD) is caused by mutations in which gene and predominantly affects which organ system besides the kidney?','["A. PKD1 on chromosome 16; affects the liver causing portal hypertension","B. PKHD1 on chromosome 6 (encoding fibrocystin/polyductin); affects the liver — biliary ductal plate malformation and congenital hepatic fibrosis","C. PKD2 on chromosome 4; affects the cardiovascular system","D. VHL gene on chromosome 3; affects the retina and cerebellum"]','C','ARPKD is caused by mutations in PKHD1 (chromosome 6p21.2), encoding fibrocystin (also called polyductin), a protein expressed in the primary cilia of renal collecting duct cells and biliary epithelium. Liver involvement is universal — ductal plate malformation leads to congenital hepatic fibrosis and non-cirrhotic portal hypertension. Severe neonatal cases may cause Potter sequence (oligohydramnios → pulmonary hypoplasia → death).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','hard','mcq','In ADPKD, the ''two-hit hypothesis'' explains cyst formation as follows:','["A. Constitutive activation of mTOR signalling is sufficient to cause cysts from birth","B. Both PKD1 alleles must be mutated (germline mutation + somatic second hit in individual tubular cells) for cyst formation in that tubule","C. Inflammation triggers Wnt pathway activation causing cyst formation","D. Loss of one PKD1 allele is sufficient to cause cysts because of haploinsufficiency"]','D','The two-hit hypothesis for ADPKD posits that patients inherit one mutated PKD1 (or PKD2) allele. A second somatic mutation (''second hit'') in the remaining normal allele in individual tubular cells leads to complete loss of polycystin function in those cells, triggering cyst formation. This explains why ADPKD is dominantly inherited (one allele mutated in all cells) yet cysts are focal — only cells that acquire a second somatic hit form cysts.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','easy','mcq','What are the typical gross pathological features of ADPKD kidneys?','["A. Normal-sized kidneys with small subcortical cysts","B. Massively enlarged bilateral kidneys replaced by numerous cysts of varying sizes throughout cortex and medulla, with only islands of normal parenchyma","C. Unilateral enlarged kidney with a single large cyst","D. Small shrunken kidneys with multiple dilated calyces"]','A','ADPKD kidneys are massively enlarged (sometimes weighing 4 kg each) and completely replaced by innumerable cysts of varying sizes (from millimetres to centimetres) derived from all segments of the nephron. The cysts are bilateral and may contain haemorrhagic or clear fluid. Normal parenchyma is progressively lost as cysts enlarge, eventually causing ESRD in the 4th-6th decade.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','medium','mcq','A 35-year-old man with known ADPKD presents with the worst headache of his life. What is the most feared intracranial complication that must be excluded?','["A. Subdural haematoma from hypertensive fall","B. Subarachnoid haemorrhage from rupture of an intracranial (Berry) aneurysm","C. Cerebral venous sinus thrombosis","D. Hypertensive intracerebral haemorrhage"]','B','Intracranial (Berry) aneurysms occur in approximately 10-40% of ADPKD patients (compared to ~1-2% in the general population). Aneurysm rupture causes subarachnoid haemorrhage, presenting with ''thunderclap'' headache (''worst headache of my life''). SAH carries high morbidity and mortality. Screening with MRA is recommended for ADPKD patients with family history of SAH or intracranial aneurysm.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','hard','mcq','In ARPKD, cysts predominantly arise from which tubular segment, and what is the characteristic gross appearance?','["A. Cortical glomeruli — bilateral small cortical cysts","B. Collecting ducts — elongated radially oriented (''sponge-like'') cysts from cortex to medulla","C. Proximal tubules — medullary cysts","D. Distal tubules — random cortical and medullary cysts"]','C','ARPKD cysts arise predominantly from the collecting ducts and are elongated, cylindrical/fusiform, and arranged radially from cortex to medulla, giving the cut kidney a sponge-like or ''Swiss cheese'' appearance. This contrasts with ADPKD where cysts arise from all nephron segments and are spherical. The elongated collecting duct cysts produce the characteristic radiating pattern seen on imaging.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','medium','mcq','Tolvaptan is used in ADPKD because it inhibits which receptor, thereby slowing cyst growth?','["A. Angiotensin II type 1 receptor (AT1R)","B. Vasopressin V2 receptor (V2R) in collecting duct cells","C. mTOR complex 1 (mTORC1)","D. Epidermal growth factor receptor (EGFR)"]','D','Tolvaptan is a selective vasopressin V2 receptor (V2R) antagonist. In ADPKD, V2R stimulation by ADH elevates cAMP in collecting duct cells, which drives cyst cell proliferation and fluid secretion. Tolvaptan blocks V2R, reducing cAMP, thereby slowing cyst growth and preserving kidney function. It is approved for patients with ADPKD at risk of rapid progression. Hepatotoxicity is an important adverse effect requiring monitoring.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','easy','mcq','A neonate with massively enlarged echogenic kidneys on ultrasound, oligohydramnios, and pulmonary hypoplasia dies shortly after birth. What is the most likely diagnosis?','["A. ADPKD presenting in the neonatal period","B. Autosomal recessive polycystic kidney disease (ARPKD) — severe perinatal form","C. Multicystic dysplastic kidney","D. Bilateral Wilms tumour"]','A','Severe perinatal ARPKD presents with massively enlarged echogenic kidneys (innumerable tiny cysts too small to resolve individually on US, causing hyperechogenicity) causing oligohydramnios (reduced fetal urine output) leading to Potter sequence: pulmonary hypoplasia, characteristic facies, and limb deformities. This form is often fatal in the neonatal period from respiratory failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Polycystic Kidney Disease','hard','mcq','Medullary sponge kidney differs from ARPKD in which key aspect?','["A. Medullary sponge kidney involves the cortex; ARPKD involves the medulla","B. Medullary sponge kidney is a non-hereditary developmental anomaly with cystic dilatation of inner medullary collecting ducts, presenting with nephrolithiasis and UTIs — not progressive renal failure","C. Medullary sponge kidney affects both kidneys and liver; ARPKD only affects kidneys","D. Medullary sponge kidney is caused by PKD1 mutation; ARPKD by PKHD1"]','B','Medullary sponge kidney (MSK) is characterised by cystic dilatation of the inner medullary and papillary collecting ducts. It is typically non-hereditary (sporadic) and usually does not cause progressive renal failure. Patients present with complications: recurrent nephrolithiasis, haematuria, and UTIs. It is detected by IVP showing a ''brush'' or ''paintbrush'' appearance in the papillae. Prognosis is generally good with complication management.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','easy','mcq','What is the most common type of renal calculus?','["A. Calcium oxalate (or calcium oxalate mixed with calcium phosphate) — approximately 70%","B. Struvite (magnesium ammonium phosphate) — approximately 40%","C. Uric acid — approximately 30%","D. Cystine — approximately 15%"]','A','Calcium stones are the most common, accounting for ~70% of all renal calculi. They are composed of calcium oxalate, or calcium oxalate mixed with calcium phosphate. Risk factors include hypercalciuria, hyperoxaluria, hypocitraturia, and low urine volume. They are radiopaque on plain X-ray. Struvite stones are ~15%, uric acid ~5-10%, and cystine ~1-2%.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','medium','mcq','Struvite (triple phosphate/staghorn) calculi are associated with infection by which type of organisms, and why?','["A. Gram-negative enteric organisms such as E. coli that produce urease, splitting urea into ammonium and alkalinising the urine — favouring magnesium ammonium phosphate precipitation","B. Urease-producing organisms (e.g., Proteus mirabilis, Klebsiella, Pseudomonas) that produce ammonia, alkalinise the urine, and promote struvite crystallisation","C. Gram-positive organisms (Staphylococcus aureus) releasing calcium-binding toxins","D. Acid-producing organisms that lower urinary pH below 5.5"]','B','Struvite (magnesium ammonium phosphate / ''triple phosphate'') stones are caused by urease-producing bacteria — most commonly Proteus mirabilis, but also Klebsiella, Pseudomonas, and Enterococcus. Urease splits urea into ammonium (NH4+) and CO2, alkalinising the urine (pH >7) and increasing ammonium concentration, which combines with magnesium and phosphate to form struvite crystals. E. coli does NOT produce urease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','medium','mcq','Which type of renal calculus is radiolucent on plain X-ray (KUB) and can be dissolved with urinary alkalinisation?','["A. Calcium oxalate","B. Calcium phosphate","C. Uric acid","D. Cystine"]','C','Uric acid stones are the only common renal calculi that are radiolucent on plain X-ray (KUB) because they do not contain calcium. They are visible on CT scan (non-contrast). They form in acidic urine (pH <5.5) in patients with hyperuricosuria, gout, metabolic syndrome, or after chemotherapy (tumour lysis). Urinary alkalinisation (potassium citrate to pH 6.5-7) can dissolve existing uric acid stones. Cystine stones are also poorly radio-opaque.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','hard','mcq','Primary hyperoxaluria type 1 (alanine-glyoxylate aminotransferase deficiency) causes which type of renal calculi, and what is the key metabolic defect?','["A. Calcium phosphate stones due to hypercalcaemia from parathyroid hormone elevation","B. Cystine stones due to defective amino acid transporter","C. Calcium oxalate stones due to massive endogenous oxalate overproduction from glyoxylate accumulation","D. Struvite stones due to impaired immune response to urinary infections"]','D','Primary hyperoxaluria type 1 is caused by deficiency of alanine-glyoxylate aminotransferase (AGT) in liver peroxisomes, normally converting glyoxylate to glycine. Without AGT, glyoxylate accumulates and is oxidised to oxalate, causing massive oxaluria and calcium oxalate nephrolithiasis/nephrocalcinosis from early childhood. Liver transplantation corrects the metabolic defect. Vitamin B6 (pyridoxine) reduces oxalate in some patients by shifting glyoxylate metabolism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','easy','mcq','Which metabolic condition is most commonly associated with calcium renal calculi?','["A. Idiopathic hypercalciuria (absorptive or renal leak)","B. Hyperuricaemia","C. Cystinuria","D. Hyperphosphataemia"]','A','Idiopathic hypercalciuria is the most common metabolic abnormality in patients with calcium oxalate/phosphate stones. It can be absorptive (excess intestinal calcium absorption), renal leak (impaired tubular calcium reabsorption), or resortive (excess bone resorption). Other risk factors for calcium stones include hyperparathyroidism, vitamin D excess, and Cushing syndrome.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','medium','mcq','Cystinuria is caused by defective transport of which amino acids in the renal tubule and intestine, predisposing to cystine stone formation?','["A. Neutral amino acids (leucine, isoleucine, valine)","B. Acidic amino acids (glutamate, aspartate)","C. Dibasic amino acids (cystine, ornithine, arginine, lysine — ''COAL'')","D. Aromatic amino acids (phenylalanine, tyrosine, tryptophan)"]','B','Cystinuria is an autosomal recessive disorder of the renal tubular and intestinal transporter for dibasic amino acids: Cystine, Ornithine, Arginine, and Lysine (COAL). Cystine is the least soluble and precipitates in urine (especially at pH <7), forming pale yellow, waxy hexagonal crystals and stones. Stones are poorly radiopaque. Treatment includes hydration, urinary alkalinisation, and D-penicillamine or tiopronin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','hard','mcq','Randall plaques are subepithelial calcium phosphate deposits in the renal papillae. What is their clinical significance?','["A. They are a direct cause of renal cell carcinoma","B. They represent the nidus for idiopathic calcium oxalate stone formation — stones grow on exposed Randall plaques when papillary epithelium erodes","C. They indicate chronic pyelonephritis","D. They are found exclusively in patients with primary hyperparathyroidism"]','C','Randall plaques are subepithelial interstitial calcium phosphate deposits in the renal papillae, first described by Alexander Randall. Current evidence supports that in idiopathic calcium oxalate stone formers, these plaques gradually erode through the papillary urothelium and become exposed to urine, where they serve as a nidus for calcium oxalate crystal deposition and stone growth. They are a key mechanism of calcium stone formation in hypercalciuric patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','medium','mcq','What is the initial investigation of choice for suspected acute renal colic?','["A. Plain X-ray (KUB) — detects all renal stones","B. Intravenous urogram (IVU) with contrast","C. Non-contrast CT of the kidneys, ureters, and bladder (CTKUB)","D. Ultrasound of the urinary tract"]','D','Non-contrast CT KUB (CTKUB) is the gold standard and investigation of choice for suspected acute renal colic. It has sensitivity >95% and specificity >97%, can detect all stone types (including radiolucent uric acid stones), and can identify alternative diagnoses. Ultrasound is preferred in pregnant women and children to avoid radiation. Plain X-ray misses radiolucent stones and is insufficiently sensitive.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','easy','mcq','Hyperuricaemia is a risk factor for which type of renal calculi?','["A. Uric acid stones and also calcium oxalate stones (urate promotes calcium oxalate crystallisation)","B. Struvite stones only","C. Cystine stones only","D. Calcium phosphate stones only"]','A','Hyperuricaemia and hyperuricosuria predispose to both uric acid stones (low pH, supersaturation of urate) and calcium oxalate stones (monosodium urate crystals act as a nidus for calcium oxalate crystallisation — ''epitaxy''). Gout, myeloproliferative disorders, dietary purine excess, and drugs (thiazides, ciclosporin) can all cause hyperuricaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Calculi','hard','mcq','In medullary sponge kidney, which stone type most commonly forms and why?','["A. Uric acid stones — due to hyperuricaemia from medullary tubular dysfunction","B. Cystine stones — due to reduced cystine transport in dilated ducts","C. Calcium oxalate and calcium phosphate stones — due to urinary stasis in dilated inner medullary collecting ducts, hypercalciuria, and impaired acidification","D. Struvite stones — due to persistent alkaline urine"]','B','In medullary sponge kidney, cystic dilatation of the inner medullary collecting ducts causes urinary stasis, impaired urinary acidification (causing distal RTA type 1), and hypercalciuria — all of which promote calcium stone formation (calcium oxalate and calcium phosphate). Stasis also predisposes to UTIs, potentially leading to struvite stones. The sponge-like medullary cysts are readily visualised on intravenous pyelography.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','easy','mcq','Clear cell renal cell carcinoma (ccRCC), the most common subtype of RCC, is associated with mutation of which tumour suppressor gene?','["A. VHL (von Hippel-Lindau) tumour suppressor gene on chromosome 3p","B. RB1 gene on chromosome 13","C. TP53 gene on chromosome 17","D. PTEN gene on chromosome 10"]','A','Clear cell RCC is the most common subtype (~70-80% of RCC). It is associated with loss of function of the VHL tumour suppressor gene (chromosome 3p25.3) in both sporadic cases (~90%) and hereditary von Hippel-Lindau syndrome. VHL normally targets HIF-1alpha for ubiquitin-mediated degradation. Loss of VHL → stabilisation of HIF → transcription of VEGF, PDGF, and EPO → angiogenesis and tumour growth.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','medium','mcq','The classic clinical triad of renal cell carcinoma includes:','["A. Flank pain, haematuria, and a palpable abdominal mass","B. Fever, weight loss, and night sweats","C. Haematuria, proteinuria, and hypertension","D. Polycythaemia, hypertension, and hypercalcaemia"]','B','The classic triad of RCC is costovertebral angle (flank) pain, gross haematuria, and a palpable abdominal mass. However, this classic triad is now seen in only ~10% of patients as most tumours are discovered incidentally on abdominal imaging. Haematuria (most common symptom) can be gross or microscopic. The triad suggests locally advanced disease.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','medium','mcq','Which paraneoplastic syndrome is associated with renal cell carcinoma due to ectopic erythropoietin production?','["A. Cushing syndrome from ectopic ACTH","B. Polycythaemia (erythrocytosis) from ectopic EPO secretion","C. SIADH from ectopic ADH secretion","D. Acromegaly from ectopic GH secretion"]','C','RCC can produce multiple paraneoplastic syndromes due to ectopic hormone secretion: polycythaemia (ectopic EPO — ~3%), hypercalcaemia (ectopic PTHrP — ~13% of patients), hypertension (ectopic renin), Cushing syndrome (ectopic ACTH), and Stauffer syndrome (non-metastatic hepatic dysfunction). These occur in ~30% of patients and can be the initial presentation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','hard','mcq','In von Hippel-Lindau (VHL) syndrome, which combination of tumours is characteristic?','["A. Clear cell RCC, cerebellar haemangioblastoma, retinal haemangioblastoma, phaeochromocytoma","B. Clear cell RCC, transitional cell carcinoma, papillary renal carcinoma","C. Clear cell RCC, Wilms tumour, hepatocellular carcinoma","D. Phaeochromocytoma, medullary thyroid carcinoma, parathyroid hyperplasia"]','D','VHL syndrome (autosomal dominant, VHL gene mutation on 3p) is characterised by: clear cell RCC (bilateral, multifocal), cerebellar and spinal haemangioblastomas, retinal haemangioblastomas (von Hippel lesions), renal and pancreatic cysts, phaeochromocytoma (in VHL type 2), and endolymphatic sac tumours. Patients require lifelong surveillance as RCC develops in ~70% of VHL patients by age 60.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','easy','mcq','On gross pathology, clear cell RCC characteristically shows which appearance?','["A. Homogeneous white-tan firm tumour","B. Variegated yellow, brown, and haemorrhagic cut surface (due to lipid and glycogen content in clear cells)","C. Papillary grey-tan tumour with calcifications","D. Uniform dark brown tumour with central necrosis"]','A','Clear cell RCC shows a characteristic variegated yellow (from lipid-laden clear cells), orange-tan, haemorrhagic, and necrotic cut surface. The yellow colour is due to the abundant cytoplasmic lipid and glycogen in tumour cells that dissolves during histological processing, leaving the cytoplasm ''clear''. It arises from the proximal tubule and typically grows as a unilateral, solitary, well-circumscribed mass.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','medium','mcq','What is the primary route of spread of renal cell carcinoma, and what is the classic vascular feature?','["A. Lymphatic spread to para-aortic nodes is primary; vascular spread does not occur","B. Haematogenous spread is primary; RCC classically invades the renal vein and may extend as a tumour thrombus into the inferior vena cava (IVC) and even the right atrium","C. Direct extension to the adrenal gland is the primary spread; IVC involvement is rare","D. Transperitoneal spread to the peritoneum is primary"]','B','RCC has a propensity for haematogenous spread (to lungs — ''cannonball'' metastases, bone, liver, brain, and adrenal glands). Its most distinctive feature is invasion into the renal vein, with tumour thrombus extending into the IVC in up to 10% of cases, and rarely into the right atrium. This complicates surgical resection and requires IVC/right atrial thrombus removal. Common metastatic sites: lung (50%), bone (33%), liver (33%).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','hard','mcq','Papillary renal cell carcinoma (pRCC) differs from clear cell RCC in which genetic alteration?','["A. Loss of VHL gene on chromosome 3p","B. MET proto-oncogene activation (chromosome 7q31) or trisomy 7 and trisomy 17","C. PBRM1 mutation on chromosome 3p","D. FLCN (folliculin) gene mutation"]','C','Papillary RCC (~15% of RCC) is associated with gain-of-function mutations in the MET proto-oncogene (c-MET — chromosome 7q31) in hereditary cases (hereditary papillary RCC syndrome), or trisomy 7, trisomy 17, and loss of chromosome Y in sporadic cases. Unlike ccRCC, papillary RCC does not have VHL mutations. FLCN mutations cause Birt-Hogg-Dube syndrome (chromophobe RCC); PBRM1 is also a ccRCC-associated gene.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','medium','mcq','Which TNM staging feature of RCC indicates T3 disease?','["A. Tumour confined to the kidney, ≤4 cm (T1a)","B. Tumour extends into major veins (renal vein or IVC) or perinephric tissues but not beyond Gerota fascia","C. Tumour extends beyond Gerota fascia or directly invades the adrenal gland","D. Tumour >7 cm confined to kidney (T2b)"]','D','RCC staging T3 indicates tumour extending into major veins (renal vein — T3a, or IVC below diaphragm — T3b, or IVC above diaphragm — T3c) or into perinephric fat but NOT beyond Gerota fascia, or ipsilateral adrenal gland involvement. T4 = extension beyond Gerota fascia. T1a = ≤4 cm in kidney; T1b = 4-7 cm; T2a = >7 cm; T2b = >10 cm, both confined to kidney.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','easy','mcq','Which imaging modality is considered the gold standard for staging renal cell carcinoma?','["A. Ultrasound of the abdomen","B. Plain X-ray of the chest and abdomen","C. CT scan of the chest, abdomen, and pelvis with IV contrast","D. MRI of the abdomen with gadolinium"]','A','Contrast-enhanced CT of the chest, abdomen, and pelvis is the gold standard for staging RCC. It characterises the primary tumour, detects renal vein/IVC invasion, identifies lymph node involvement, and detects distant metastases (lung, liver, adrenal, bone). MRI is preferred when IVC thrombus extent needs delineation or when CT contrast is contraindicated. Bone scan is added if skeletal metastases are suspected.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renal Cell Carcinoma','hard','mcq','Sunitinib, pazopanib, and sorafenib target which pathway that is constitutively activated in VHL-deficient clear cell RCC?','["A. EGFR signalling pathway","B. mTOR/PI3K signalling pathway","C. VEGF receptor (VEGFR) and PDGF receptor signalling — angiogenic pathway activated by HIF upregulation","D. ALK fusion kinase pathway"]','B','In VHL-deficient ccRCC, loss of VHL leads to HIF-1alpha and HIF-2alpha stabilisation, which drives transcription of VEGF, PDGF, and other angiogenic factors. This creates a highly vascularised tumour dependent on VEGF-driven angiogenesis. Sunitinib, pazopanib, cabozantinib, and axitinib are multi-targeted tyrosine kinase inhibitors that block VEGFR-1, -2, -3 and PDGFR, cutting off the tumour blood supply. mTOR inhibitors (everolimus, temsirolimus) block a parallel pathway.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','easy','mcq','What is the most common malignant tumour of the urinary bladder?','["A. Urothelial (transitional cell) carcinoma","B. Squamous cell carcinoma","C. Adenocarcinoma","D. Small cell carcinoma"]','A','Urothelial (transitional cell) carcinoma is the most common bladder malignancy, accounting for ~90% of all bladder cancers. Squamous cell carcinoma accounts for ~5% (associated with chronic inflammation, Schistosoma haematobium infection in endemic areas) and adenocarcinoma ~2% (associated with urachal remnants or bladder exstrophy). Urothelial carcinoma can arise anywhere in the urothelial tract — bladder (most common), renal pelvis, ureter, urethra.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','medium','mcq','Which occupational exposure carries the highest risk for urothelial carcinoma of the bladder?','["A. Asbestos exposure in construction workers","B. Aromatic amine (2-naphthylamine, benzidine, aniline dye) exposure in rubber, dye, and paint industries","C. Silica dust exposure in miners","D. Formaldehyde exposure in laboratory workers"]','B','Aromatic amines — particularly 2-naphthylamine and benzidine — are the most potent occupational carcinogens for bladder cancer, historically used in rubber, aniline dye, leather, and paint industries. They undergo hepatic hydroxylation and glucuronidation, and are then excreted in urine where glucuronidase in bladder epithelium regenerates the reactive hydroxylamine carcinogen that directly damages urothelial DNA. Latency period is 15-40 years.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','medium','mcq','Cigarette smoking increases the risk of urothelial carcinoma through which mechanism?','["A. Direct physical irritation of the bladder mucosa from smoke particles","B. Nicotine-induced immunosuppression","C. Urinary excretion of aromatic amines (2-naphthylamine, 4-aminobiphenyl) and other carcinogens from tobacco smoke that contact the urothelium","D. Carbon monoxide causing chronic bladder ischaemia"]','C','Cigarette smoking is the most important risk factor for bladder cancer, increasing risk 2-4 times. Tobacco smoke contains aromatic amines (2-naphthylamine, 4-aminobiphenyl) and polycyclic aromatic hydrocarbons that are absorbed, metabolically activated, and excreted in urine where they act directly on the urothelium. Smoking accounts for approximately 50% of bladder cancers in men and 35% in women.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','hard','mcq','Carcinoma in situ (CIS) of the bladder is characterised by which features and what is its clinical significance?','["A. Flat, non-invasive, high-grade urothelial dysplasia confined to the epithelium — carries high risk of progression to muscle-invasive disease","B. Papillary low-grade tumour with excellent prognosis and low recurrence","C. Benign urothelial metaplasia without malignant potential","D. Invasive tumour through muscularis propria with worse prognosis than stage T3"]','D','Bladder CIS (carcinoma in situ, pTis) is a flat, non-papillary, non-invasive but high-grade urothelial carcinoma confined to the epithelium. It appears red, velvety, or granular on cystoscopy. Despite being ''in situ'', CIS carries a significantly higher risk of progression to muscle-invasive bladder cancer (~54% at 5 years if untreated) compared to low-grade papillary tumours. Treatment is intravesical BCG immunotherapy. It may co-exist with invasive tumours.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','easy','mcq','Schistosoma haematobium infection of the bladder is associated with which type of bladder cancer?','["A. Urothelial (transitional cell) carcinoma","B. Squamous cell carcinoma","C. Adenocarcinoma","D. Lymphoma"]','A','Schistosoma haematobium infection is a major risk factor for squamous cell carcinoma of the bladder, particularly in Sub-Saharan Africa, the Middle East, and Egypt. Chronic granulomatous inflammation from schistosome eggs deposited in the bladder wall causes chronic squamous metaplasia, dysplasia, and ultimately squamous cell carcinoma. This is a classic example of inflammation-associated carcinogenesis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','medium','mcq','Which molecular alteration characterises the ''papillary pathway'' of low-grade non-invasive urothelial carcinoma?','["A. TP53 mutation and RB1 loss","B. FGFR3 mutation and PIK3CA mutation — leading to activation of proliferative signalling","C. KRAS mutation and PTEN loss","D. BRCA2 mutation and CDH1 loss"]','B','Bladder cancer follows two main molecular pathways: (1) Papillary pathway (low-grade): FGFR3 activating mutations and RAS mutations → papillary tumours, low invasion risk, good prognosis. (2) CIS/invasive pathway (high-grade): TP53 mutation, RB1 loss, and CDKN2A (p16) loss → flat high-grade lesions with high invasion and metastasis potential. These two pathways have distinct molecular profiles and clinical behaviour.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','hard','mcq','Cyclophosphamide use is associated with haemorrhagic cystitis and bladder cancer through which mechanism?','["A. Cyclophosphamide is directly carcinogenic to the urothelium via alkylation","B. The metabolite acrolein (released in urine) directly damages urothelial DNA and causes haemorrhagic cystitis and urothelial carcinoma","C. Cyclophosphamide causes immunosuppression, increasing HPV-associated bladder cancer risk","D. Cyclophosphamide metabolites form reactive oxygen species that damage bladder vasculature"]','C','Cyclophosphamide is metabolised to active alkylating agents (phosphoramide mustard) and a toxic by-product acrolein, which is excreted in urine. Acrolein directly damages urothelial cells causing haemorrhagic cystitis (acute complication) and urothelial DNA damage increasing risk of bladder cancer (long-term risk). Mesna (2-mercaptoethane sulphonate) is given prophylactically to bind and detoxify acrolein in urine.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','medium','mcq','What is the most common presenting symptom of bladder carcinoma?','["A. Painless gross haematuria","B. Dysuria and urinary frequency","C. Flank pain and hydronephrosis","D. Pelvic mass and constipation"]','D','Painless gross haematuria (intermittent or continuous) is the most common presenting symptom of bladder carcinoma, occurring in ~85% of patients. ''Painless'' distinguishes it from haematuria from stones or infection (which are painful). Any patient over 45 with unexplained visible haematuria requires urgent cystoscopy to exclude bladder cancer. Irritative symptoms (frequency, urgency) may accompany CIS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','easy','mcq','What is the definitive investigation and standard diagnostic procedure for suspected bladder carcinoma?','["A. CT urogram with post-void films","B. Urine cytology with Papanicolaou staining","C. Cystoscopy with biopsy and TURBT (transurethral resection of bladder tumour)","D. MRI pelvis with gadolinium contrast"]','A','Cystoscopy with biopsy and TURBT (transurethral resection of bladder tumour) is the gold standard diagnostic and therapeutic procedure for bladder carcinoma. It allows direct visualisation of the lesion, biopsy for histological diagnosis and staging (including assessment of muscularis propria invasion), and complete resection of non-invasive tumours. Urine cytology is useful for high-grade tumours and CIS but has poor sensitivity for low-grade tumours.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Bladder Pathology','hard','mcq','Phenacetin abuse was historically associated with urothelial carcinomas at which anatomical site?','["A. Bladder trigone","B. Renal pelvis (urothelial carcinoma of the upper urinary tract) and ureter","C. Bladder dome (urachal adenocarcinoma)","D. Bladder neck and urethra"]','B','Long-term phenacetin (and NSAID) abuse causes analgesic nephropathy — papillary necrosis and chronic interstitial nephritis — and significantly increases the risk of urothelial carcinoma of the renal pelvis and ureter (upper tract urothelial carcinoma). The mechanism involves phenacetin metabolites (particularly acetaminophen) acting as urinary carcinogens. This association led to the withdrawal of phenacetin-containing analgesics in many countries.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','easy','mcq','The two most common causes of renal artery stenosis leading to renovascular hypertension are:','["A. Atherosclerosis (older patients, ostial lesion) and fibromuscular dysplasia (younger women, mid/distal artery)","B. Vasculitis and renal artery thrombosis","C. Polyarteritis nodosa and Takayasu arteritis","D. Aortic dissection and renal artery aneurysm"]','A','Renal artery stenosis has two main causes: (1) Atherosclerosis — the most common cause (>90%), typically affecting the proximal 1/3 and ostium of the renal artery in older men with cardiovascular risk factors; (2) Fibromuscular dysplasia (FMD) — affects the mid and distal artery in young-to-middle-aged women, with a characteristic ''string of beads'' appearance on angiography from alternating stenoses and aneurysms (medial fibroplasia is the most common FMD subtype).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','medium','mcq','The Goldblatt kidney model demonstrated that renal artery stenosis causes hypertension through which mechanism?','["A. Renal artery stenosis causes direct inflammation of the kidney","B. Reduced renal perfusion pressure activates the renin-angiotensin-aldosterone system (RAAS) — increased renin → angiotensin II → vasoconstriction and aldosterone-mediated sodium retention → hypertension","C. Renal artery stenosis causes polycythaemia which increases blood viscosity","D. Reduced renal perfusion suppresses EPO causing anaemia-induced cardiac output increase"]','B','Renal artery stenosis reduces perfusion pressure to the juxtaglomerular apparatus, which responds by increasing renin secretion. Renin converts angiotensinogen to angiotensin I → ACE converts it to angiotensin II → potent vasoconstriction and aldosterone release → sodium/water retention and further vasoconstriction → hypertension. This is a classic example of ''secondary hypertension'' and explains why ACE inhibitors and ARBs can precipitate acute kidney injury in bilateral RAS (or RAS in a single functioning kidney).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','medium','mcq','A kidney distal to a chronic unilateral renal artery stenosis classically shows which gross pathological change?','["A. Enlargement with multiple cortical cysts","B. Ischaemic nephrosclerosis — small, shrunken kidney with fine granular surface (due to ischaemic atrophy from chronic hypoperfusion)","C. Haemorrhagic infarction with wedge-shaped pale areas","D. Normal gross appearance with only microscopic changes"]','C','Chronic unilateral renal artery stenosis causes ischaemic nephrosclerosis in the affected kidney — it becomes small, shrunken, and pale with a fine granular surface from ischaemic atrophy of nephrons. The contralateral non-stenosed kidney undergoes hypertensive nephrosclerosis and may show compensatory hypertrophy. This explains the asymmetry of kidney size on imaging (difference >1.5 cm) that raises suspicion for renovascular hypertension.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','hard','mcq','Renal atheroembolic disease (atheroembolism to the kidney) most commonly occurs in which clinical setting and shows which pathological finding?','["A. Young patients with FMD after percutaneous transluminal angioplasty","B. Elderly patients with severe aortic atherosclerosis after vascular instrumentation (angiography, aortic surgery) — kidney shows cholesterol clefts (biconvex needle-shaped clefts) in interlobular arteries with giant cell reaction","C. Patients with infective endocarditis — septic emboli to renal cortex","D. Patients with antiphospholipid syndrome — platelet thrombi in glomeruli"]','D','Atheroembolic renal disease occurs in elderly patients with severe aortic atherosclerosis, typically triggered by vascular procedures (catheterisation, angioplasty, aortic surgery) or spontaneously. Cholesterol crystals dislodge from atheromatous plaques and lodge in medium and small renal arteries. Histologically, cholesterol crystal emboli appear as biconvex needle-shaped clefts (crystals dissolve in processing) with surrounding giant cell reaction, intimal thickening, and eventually fibrosis. It may cause acute or subacute renal failure.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','easy','mcq','Malignant nephrosclerosis (malignant hypertension) is associated with which distinctive vascular lesion?','["A. Hyaline arteriolosclerosis with pink amorphous material in arteriolar walls","B. Hyperplastic arteriolosclerosis — ''onion-skin'' concentric intimal proliferation in interlobular arteries and fibrinoid necrosis of arterioles","C. Atherosclerotic plaques in main renal arteries","D. Cholesterol clefts in small arteries"]','A','Malignant hypertension (diastolic BP >120 mmHg with end-organ damage) causes two characteristic vascular lesions in the kidney: (1) Hyperplastic arteriolosclerosis — ''onion-skin'' concentric proliferation of smooth muscle cells and fibroblasts in interlobular arteries, and (2) Fibrinoid necrosis of afferent arterioles. These lesions cause ischaemia and the kidneys show petechial haemorrhages (flea-bitten appearance) from rupture of arterioles.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','medium','mcq','Renal vein thrombosis is a recognised complication of which conditions?','["A. Membranous nephropathy (heavy proteinuria causing antithrombin III loss), nephrotic syndrome, and renal cell carcinoma (tumour thrombus)","B. Acute pyelonephritis and IgA nephropathy","C. Polycystic kidney disease and medullary sponge kidney","D. CKD stage 5 and diabetic nephropathy"]','B','Renal vein thrombosis (RVT) is associated with: (1) Nephrotic syndrome — particularly membranous nephropathy — due to urinary loss of antithrombin III, protein C, and protein S, creating a hypercoagulable state; (2) RCC — tumour thrombus directly extends into renal vein; (3) Extrinsic compression by tumour; (4) Dehydration in neonates; (5) Antiphospholipid syndrome. Membranous nephropathy has the highest rate of RVT (~35%).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','hard','mcq','Benign nephrosclerosis (associated with chronic hypertension and ageing) is characterised histologically by which changes?','["A. Glomerular crescent formation and interstitial eosinophilia","B. Hyaline arteriolosclerosis (homogeneous eosinophilic thickening of arteriolar walls), ischaemic glomerulosclerosis, and tubular atrophy","C. Subepithelial spike deposits and podocyte effacement","D. Mesangial IgA deposits with mesangial hypercellularity"]','C','Benign nephrosclerosis (from chronic hypertension or ageing) shows: (1) Hyaline arteriolosclerosis — amorphous pink hyaline deposits in the wall of afferent arterioles, causing luminal narrowing; (2) Intimal fibrosis of interlobular arteries; (3) Ischaemic glomerulosclerosis (global glomerular collapse from ischaemia); (4) Tubular atrophy with interstitial fibrosis. Mild benign nephrosclerosis is expected with ageing; it becomes clinically significant with severe chronic hypertension.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','medium','mcq','Thrombotic microangiopathy (TMA) affecting the kidney includes HUS and TTP. Which finding distinguishes TMA from glomerulonephritis on renal biopsy?','["A. Crescents in Bowman space — only seen in TMA","B. Microthrombi in glomerular capillaries and small arterioles without immune complex deposits on immunofluorescence","C. Linear IgG deposits along the GBM","D. Massive proteinuria with effacement of foot processes"]','D','Thrombotic microangiopathy (TMA) in HUS/TTP shows platelet-fibrin microthrombi occluding glomerular capillaries and arterioles, endothelial swelling, and double-contoured GBM. Critically, immunofluorescence is NEGATIVE for immunoglobulins and complement (unlike immune complex GN). In HUS, thrombi are predominantly in the kidney; in TTP, they are more widespread (involving brain, heart, kidney). The distinction matters: plasma exchange for TTP, supportive care for typical (STEC) HUS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','easy','mcq','Fibromuscular dysplasia (FMD) of the renal artery most commonly affects which layer of the arterial wall?','["A. Intima — causing intimal fibroplasia","B. Media — causing medial fibroplasia (most common, ~75-80% of FMD cases)","C. Adventitia — causing periadventitial fibroplasia","D. All three layers equally"]','A','Fibromuscular dysplasia of the renal artery exists in three forms by layer affected: (1) Medial fibroplasia — the most common (~75-80% of FMD), causing the classic ''string of beads'' pattern on angiography (alternating stenoses and microaneurysms); (2) Perimedial fibroplasia; (3) Intimal fibroplasia (rarest). Medial FMD affects young women and is bilateral in ~35% of cases. Treatment is percutaneous transluminal angioplasty (PTA).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Renovascular Disease','hard','mcq','In renal artery stenosis, ACE inhibitors can precipitate acute kidney injury. What is the mechanism?','["A. ACE inhibitors cause systemic hypotension reducing total renal perfusion pressure","B. In bilateral RAS (or RAS in a single kidney), GFR is maintained by angiotensin II-mediated efferent arteriolar constriction. ACE inhibitors block angiotensin II, dilate the efferent arteriole, and precipitously drop glomerular capillary pressure and GFR","C. ACE inhibitors promote renin release, worsening the primary pathology","D. ACE inhibitors cause renal vein thrombosis by activating the coagulation cascade"]','B','In bilateral renal artery stenosis or stenosis of a single functioning kidney, GFR is maintained by angiotensin II-mediated efferent arteriolar vasoconstriction, which maintains glomerular hydrostatic pressure. ACE inhibitors block angiotensin II synthesis, causing efferent arteriolar dilation, a sharp drop in glomerular capillary pressure, and acute decline in GFR. This is why an acute rise in creatinine (>30%) after starting ACE inhibitor/ARB should prompt investigation for bilateral RAS.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','easy','mcq','What is the most common causative organism of community-acquired urinary tract infection?','["A. Escherichia coli (E. coli)","B. Staphylococcus saprophyticus","C. Klebsiella pneumoniae","D. Proteus mirabilis"]','A','E. coli causes ~80% of community-acquired UTIs. It possesses virulence factors including type 1 fimbriae (binding to uroplakin and mannose-containing receptors in the bladder), P fimbriae (binding to P blood group antigen on urothelial cells — important for pyelonephritis), and flagella. Staphylococcus saprophyticus is the second most common in young sexually active women. Klebsiella and Proteus are more common in hospital-acquired UTIs.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','medium','mcq','Which route of infection is responsible for the vast majority of pyelonephritis cases?','["A. Haematogenous (blood-borne) seeding from bacteraemia","B. Ascending infection — from the periurethra → bladder → ureter → renal pelvis → renal parenchyma","C. Lymphatic spread from pelvic organs","D. Direct spread from adjacent pelvic organs"]','B','The ascending route accounts for the vast majority (>95%) of cases of pyelonephritis. Faecal flora colonise the periurethra → catheterisation or turbulent urine flow introduces organisms into the bladder → cystitis → ascending spread via the ureter (facilitated by vesicoureteral reflux) → renal pelvis → parenchymal infection. Short female urethra explains higher female UTI prevalence. Haematogenous spread (Staph. aureus, Candida, Mycobacterium TB) is less common.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','medium','mcq','Acute pyelonephritis macroscopically shows which distinctive appearance?','["A. Smooth pale cortex with dilated calyces","B. Discrete yellowish-white abscesses on cortical surface and in parenchyma with haemorrhagic borders, tracking along collecting ducts","C. Multiple cortical cysts with grey translucent appearance","D. Diffuse haemorrhagic cortex"]','C','Acute pyelonephritis shows discrete yellowish-white abscesses on the cortical surface and in the medullary parenchyma (from suppurative inflammation). These abscesses are often arranged in linear streaks extending from the papilla to the cortex, following collecting duct tracts. The kidney is enlarged and congested. Microscopically: suppurative interstitial inflammation (neutrophil infiltrate), tubular necrosis, and purulent exudate filling tubular lumens.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','hard','mcq','Xanthogranulomatous pyelonephritis (XGP) is a rare form of chronic renal infection characterised by which pathological features?','["A. Diffuse amyloid deposition in the interstitium","B. Granulomatous inflammation with lipid-laden macrophages (xanthoma cells) replacing renal parenchyma — associated with Proteus infection and obstructing renal calculus","C. Cholesterol crystal emboli with giant cell reaction","D. Miliary granulomas with central caseation — typical of TB"]','D','Xanthogranulomatous pyelonephritis (XGP) is a rare destructive renal infection characterised by granulomatous inflammation with sheets of lipid-laden foamy macrophages (''xanthoma cells'') replacing renal parenchyma. It is typically associated with Proteus mirabilis (or E. coli) infection, obstructing staghorn calculi, and diabetes. The affected kidney is enlarged and non-functioning. It can mimic RCC on imaging and often requires nephrectomy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','easy','mcq','White cell casts in the urine are a characteristic finding of which condition?','["A. Nephrotic syndrome","B. Acute pyelonephritis or severe acute interstitial nephritis","C. Rapidly progressive glomerulonephritis","D. Bladder carcinoma"]','A','White cell (leucocyte) casts indicate renal parenchymal infection or inflammation — they are pathognomonic for pyelonephritis (or severe interstitial nephritis). They form when neutrophils aggregate within renal tubular lumens and are embedded in Tamm-Horsfall protein. Their presence distinguishes upper UTI (pyelonephritis) from lower UTI (cystitis), where WBCs are in urine but not in cast form.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','medium','mcq','Vesicoureteral reflux (VUR) is graded I-V. Which grade is associated with the highest risk of renal scarring?','["A. Grade I — reflux into ureter only","B. Grade II — reflux into renal pelvis without dilatation","C. Grade III — reflux with mild dilatation of ureter and pelvis","D. Grade IV-V — gross dilatation of ureter and pelvis with intrarenal reflux and risk of renal scarring"]','B','VUR is graded I-V: Grade I (ureter only), Grade II (pelvis/calyces, no dilatation), Grade III (mild dilatation), Grade IV (moderate dilatation with blunted fornices), Grade V (gross dilatation, tortuosity, loss of papillary impressions). High-grade VUR (IV-V) allows infected urine to reflux into the renal parenchyma (intrarenal reflux), causing recurrent pyelonephritis and renal scarring → reflux nephropathy → CKD.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','hard','mcq','Recurrent pyelonephritis in patients with vesicoureteral reflux causes a characteristic pattern of renal scarring called reflux nephropathy. What is the histological appearance of this scar tissue?','["A. Diffuse global glomerulosclerosis","B. Interstitial lymphocytic infiltrate only","C. Thyroidisation of tubules — tubules filled with pink colloid-like material resembling thyroid follicles, surrounded by interstitial fibrosis, tubular atrophy, and periglomerular fibrosis","D. Mesangial IgA deposits with crescents"]','C','Chronic pyelonephritis/reflux nephropathy shows: (1) ''Thyroidisation'' of tubules — atrophic tubules filled with eosinophilic proteinaceous material resembling thyroid follicles; (2) Dense interstitial fibrosis; (3) Periglomerular fibrosis; (4) Glomeruli showing ischaemic changes (wrinkling and retraction of GBM) or focal segmental sclerosis (from hyperfiltration in remaining nephrons). Grossly: asymmetric coarse cortical scars overlying dilated blunted calyces.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','medium','mcq','Emphysematous pyelonephritis is a severe necrotising renal infection characterised by gas formation within the renal parenchyma. Which patient population is most at risk?','["A. Immunocompetent young adults after urinary catheterisation","B. Diabetic patients (particularly with type 2 diabetes) with E. coli or Klebsiella UTI","C. Patients with polycystic kidney disease","D. Pregnant women in the third trimester"]','D','Emphysematous pyelonephritis (EP) is a life-threatening necrotising renal infection in which gas-forming organisms (E. coli ~70%, Klebsiella ~20%) produce gas within the renal parenchyma by fermenting glucose/lactate. It occurs almost exclusively in diabetics (90%+ of cases), likely due to impaired immunity, high tissue glucose providing substrate for fermentation, and poor vascular supply. CT shows gas within the kidney. Treatment: urgent nephrostomy drainage and antibiotics; nephrectomy may be required.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','easy','mcq','Which of the following urinary findings is most specific for cystitis (lower UTI) as opposed to upper UTI?','["A. Bacteriuria and pyuria without casts","B. White cell casts","C. Red cell casts","D. Granular casts"]','A','In lower UTI (cystitis), bacteria and white blood cells are present in the urine (bacteriuria and pyuria), but urinary casts are NOT present because cast formation requires tubular involvement, which does not occur in cystitis. The absence of casts with pyuria distinguishes lower from upper UTI. White cell casts, when present, indicate pyelonephritis or interstitial nephritis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Renal System','Pathology','Urinary Tract Infection Pathology','hard','mcq','Malacoplakia is a rare granulomatous reaction associated with chronic E. coli UTI. What is the pathognomonic histological finding?','["A. Multinucleated giant cells containing calcium oxalate crystals","B. Foamy macrophages (von Hansemann cells) containing Michaelis-Gutmann bodies — targetoid calcified inclusions from incompletely digested bacterial debris","C. Non-caseating granulomas with Langhans giant cells","D. Cholesterol cleft deposits with eosinophilic infiltrate"]','B','Malacoplakia is an unusual granulomatous inflammatory reaction to chronic E. coli (or other Gram-negative) infections, especially in immunocompromised patients. Pathognomonic are Michaelis-Gutmann bodies — targetoid, laminated, calcified inclusions (PAS- and von Kossa-positive) found within von Hansemann macrophages (large granular histiocytes). These inclusions represent incompletely digested bacterial cell wall debris accumulating due to lysosomal dysfunction in macrophages.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}','Robbins & Cotran Pathologic Basis of Disease 9th Ed');